				Array.isArray(i) ? i : [i],
				newVNode,
				oldVNode,
				globalContext,
				identity.type === 'foreignObject' ? false : this.isSvg,
				hydrate.excess,
				commitQueue,
				EMPTY_OBJ,
				hydrate.hydrating
